def gen(rng):
    def fmt(ones, zeros):
        a = [1] * ones + [0] * zeros
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt(1, 0), fmt(0, 1), fmt(4, 3), fmt(5, 0), fmt(0, 4), fmt(1, 1), fmt(7, 1), fmt(1, 7)]
    for n in (2, 3, 4, 5, 8, 13, 20, 50, 100):
        for _ in range(2):
            k = rng.randint(0, n)
            tests.append(fmt(k, n - k))
    N = 10**6
    tests.append(fmt(N - 1, 1))
    tests.append(fmt(N // 2, N - N // 2))
    tests.append(fmt(N, 0))
    return tests

